-- migration 0042: পুরোনো override টেবিল বাদ দেওয়া
-- agent_overrides টেবিল যেকোনো সারিকে সিস্টেম নির্দেশ ঢোকাতে দিত।
-- v3.0 থেকে এটা আর ব্যবহার হয় না; এটা আর এর সংশ্লিষ্ট grants মুছে ফেলুন।
DROP TABLE IF EXISTS agent_overrides;
REVOKE ALL ON SCHEMA agent FROM PUBLIC;
-- ডেটা টিমকে মাইগ্রেশনের নোটিশ পাঠাতে ভুলবেন না।
